fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Assumes a.len() == b.len() as stated in the problem.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x >= y)
        .collect()
}

